\tikzset{midarrow/.style={decoration={markings, mark=at position 0.6 with {\arrow{>}}}, postaction={decorate}}}
\coordinate (M) at (3.5,2.0);
\coordinate (P) at (1.0,3.2);
\coordinate (A) at (1.5,0.5);
\coordinate (B) at (5.5,3.5);
\coordinate (S) at (6.0,1.2);
\draw[midarrow] (M) -- (P) node[pos=0.4, fill=white, inner sep=1pt] {$8$};
\draw[midarrow] (M) -- (A) node[pos=0.4, fill=white, inner sep=1pt] {$12$};
\draw[midarrow] (M) -- (B) node[pos=0.4, fill=white, inner sep=1pt] {$16$};
